/* the drive-in profile for the first trap: wrong = junction drawn at L, right = junction where C meets the wafer doping */
function VL_profile(wrong){
 const X=x=>60+x*771, Y=l=>290-(l-15)*65;
 let s=VL_L(60,290,600,290,'#ADB5BD',2)+VL_L(60,290,60,24,'#ADB5BD',2)+VL_T(600,318,'depth x (μm)',{fs:20,a:'end',fill:'#5C6577'})+VL_T(70,40,'log C',{fs:20,fill:'#5C6577'});
 let p=[];for(let i=0;i<=80;i++){const x=0.7*i/80,l=VL_logC(x);if(l<15)break;p.push(`${X(x).toFixed(1)},${Y(l).toFixed(1)}`)}
 s+=`<polyline points="${p.join(' ')}" fill="none" stroke="${BLU}" stroke-width="5" stroke-linejoin="round"/>`;
 const xL=X(VL_Lum), yL=Y(VL_logC(VL_Lum));
 if(wrong){
  s+=VL_L(xL,yL,xL,290,TRED,4,'stroke-dasharray="8 6"')+`<circle cx="${xL}" cy="${yL.toFixed(1)}" r="9" fill="${TRED}"/>`;
  s+=VL_T(xL+16,yL-8,'“junction” at L = 0.21 μm?',{fs:24,fw:800,fill:TRED})+VL_T(xL+22,yL+30,'C here = 2.0 × 10¹⁸, still n-type',{fs:20,fill:'#5C6577'});
 } else {
  const xj=X(0.522), y16=Y(16);
  s+=VL_L(60,y16,600,y16,GRN,3,'stroke-dasharray="9 6"')+VL_T(70,y16-10,'wafer doping 10¹⁶',{fs:20,fw:700,fill:GRN});
  s+=VL_L(xL,yL,xL,290,'#ADB5BD',3,'stroke-dasharray="6 6"')+VL_T(xL-24,280,'L',{fs:22,fw:800,fill:'#5C6577'});
  s+=VL_L(xj,y16,xj,290,GRN,3)+`<circle cx="${xj.toFixed(1)}" cy="${y16.toFixed(1)}" r="10" fill="${GRN}"/>`+VL_T(xj-12,264,'xⱼ = 2.51 L',{fs:24,fw:800,a:'end',fill:GRN});
 }
 return s}
function EXTRA(R,ICON){
 /* hook: one transistor with its thin gate oxide, and the furnace that grows it */
 ICON.vlChip=(x,y)=>`<g transform="translate(${x} ${y})">${VL_box(-190,-100,380,200,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${VL_T(-170,-64,'one transistor',{fs:24,fw:800,fill:BLU})}
  ${VL_rect(-170,10,340,72,VL_SI,VL_SIS)}<path d="M-150,10 Q-150,46 -100,46 Q-60,46 -60,10 Z" fill="#FFD8A8" stroke="${ORG}" stroke-width="2"/><path d="M150,10 Q150,46 100,46 Q60,46 60,10 Z" fill="#FFD8A8" stroke="${ORG}" stroke-width="2"/>
  ${VL_rect(-60,2,120,8,BLU,BLU,1)}${VL_rect(-60,-44,120,46,'#868E96','#495057',2)}${VL_T(0,-14,'gate',{fs:22,fw:800,a:'middle',fill:'#FFFFFF'})}
  ${VL_L(64,6,96,-20,ORG,2)}${VL_T(100,-26,'oxide',{fs:22,fw:800,fill:ORG})}${VL_T(100,-2,'2–10 nm',{fs:20,fw:700,fill:ORG})}${VL_T(158,72,'Si',{fs:22,fw:700,a:'end',fill:VL_SIS})}</g>`;
 ICON.vlFurnace=(x,y)=>`<g transform="translate(${x} ${y})">${VL_box(-190,-95,380,190,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${VL_T(-170,-58,'furnace, 900–1100 °C',{fs:24,fw:800,fill:ORG})}
  <rect x="-170" y="-36" width="340" height="100" rx="48" fill="#FFE8CC" stroke="${ORG}" stroke-width="3"/>
  ${[0,1,2,3,4,5,6].map(i=>VL_rect(-96+i*30,-22,8,72,'#ADB5BD','#5C6577',1.5)).join('')}
  ${VL_arrow(-160,14,-112,14,BLU,3)}${VL_T(-150,4,'O₂',{fs:20,fw:800,fill:BLU})}
  ${[0,1,2,3,4].map(i=>`<path d="M${-110+i*55},${84} q8,-8 0,-14 q-8,-6 0,-14" fill="none" stroke="${RED}" stroke-width="3" stroke-linecap="round"/>`).join('')}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.vlOx=(x,y)=>`<g transform="translate(${x} ${y})">${VL_rect(-200,40,400,100,VL_SI,VL_SIS)}${VL_rect(-200,28,190,12,BLU,BLU,1)}${VL_rect(10,-60,190,100,VL_OX,BLU,3)}
  ${VL_T(-105,10,'dry: gate',{fs:28,fw:800,a:'middle',fill:BLU})}${VL_T(105,0,'wet: field',{fs:28,fw:800,a:'middle',fill:BLU})}${VL_T(0,104,'Si',{fs:28,fw:800,a:'middle',fill:VL_SIS})}
  ${VL_T(-105,-110,'2–10 nm',{fs:24,fw:700,a:'middle',fill:'#5C6577'})}${VL_T(105,-80,'0.2–1 μm',{fs:24,fw:700,a:'middle',fill:'#5C6577'})}</g>`;
 ICON.vlDope=(x,y)=>{const X=v=>-180+v*514, Y=l=>130-(l-15)*67.5;let p=[];for(let i=0;i<=70;i++){const v=0.7*i/70,l=VL_logC(v);if(l<15)break;p.push(`${X(v).toFixed(1)},${Y(l).toFixed(1)}`)}
  const xj=X(0.522),y16=Y(16);
  return `<g transform="translate(${x} ${y})">${VL_L(-180,130,190,130,'#ADB5BD',3)}${VL_L(-180,130,-180,-150,'#ADB5BD',3)}<polyline points="${p.join(' ')}" fill="none" stroke="${ORG}" stroke-width="6" stroke-linejoin="round"/>
  ${VL_L(-180,y16,190,y16,GRN,3,'stroke-dasharray="9 6"')}<circle cx="${xj.toFixed(1)}" cy="${y16.toFixed(1)}" r="11" fill="${GRN}"/>${VL_L(xj,y16,xj,130,GRN,3)}
  ${VL_T(xj-16,y16-20,'junction',{fs:28,fw:800,a:'end',fill:GRN})}${VL_T(-20,-120,'C at the surface',{fs:24,fw:700,fill:ORG})}${VL_T(190,164,'depth',{fs:24,a:'end',fill:'#5C6577'})}</g>`};
 ICON.vlEtchI=(x,y)=>`<g transform="translate(${x} ${y})">${VL_T(-185,-148,'wet: undercuts',{fs:28,fw:800,fill:GRN})}<g transform="translate(-185 -134) scale(.9)">${VL_etch(0,0,370,110,40,true)}</g>${VL_T(-185,22,'RIE: vertical walls',{fs:28,fw:800,fill:GRN})}<g transform="translate(-185 36) scale(.9)">${VL_etch(0,0,370,110,4,false)}</g></g>`;
}
